import * as React from "react";

import { Calendar } from "@/registry/erbium/ui/calendar";
import { Card } from "@/registry/erbium/ui/card";

export function CalendarWeekNumbers() {
  const [date, setDate] = React.useState<Date | undefined>(
    () => new Date(new Date().getFullYear(), 0, 12),
  );

  return (
    <Card className="mx-auto w-fit p-0">
      <Calendar
        mode="single"
        defaultMonth={date}
        selected={date}
        onSelect={setDate}
        showWeekNumber
      />
    </Card>
  );
}

import { CalendarWeekNumbers } from "../examples/calendar-week-numbers";

const Example = () => <CalendarWeekNumbers />;

export default Example;
